#include <Wire.h>
#include <DHT.h>

// --- پین‌اوت جدید مخصوص برد ESP32-S3 ---
#define I2C_SDA_PIN     8   
#define I2C_SCL_PIN     9   
#define PIR_PIN         13  
#define DHT_PIN         4   
#define CURRENT_PIN     5   
#define LDR_PIN         6   
#define DHT_TYPE        DHT22
#define PCF8574_ADDR    0x20

DHT dht(DHT_PIN, DHT_TYPE);

int no_presence_timer = 0;
bool hvac_state = false;

void setup() {
  Serial.begin(115200);
  Wire.begin(I2C_SDA_PIN, I2C_SCL_PIN);
  dht.begin();
  pinMode(PIR_PIN, INPUT);

  Serial.println("Simulation Started on ESP32-S3...");
  writePCF8574(0x00); // خاموش کردن اولیه تمام رله‌ها
}

void loop() {
  // 1. خواندن وضعیت سنسورها
  bool presence = digitalRead(PIR_PIN);
  float temp = dht.readTemperature();

  // تبدیل ولتاژ آنالوگ به مقادیر قابل فهم
  int raw_light = analogRead(LDR_PIN);
  float lux_sim = (raw_light / 4095.0) * 1000.0; 

  int raw_current = analogRead(CURRENT_PIN);
  float current_sim = (raw_current / 4095.0) * 20.0;

  uint8_t relay_cmd = 0x00;

  // 2. چاپ اطلاعات در Virtual Terminal پروتئوس
  Serial.print("Temp: "); Serial.print(temp); Serial.print(" C | ");
  Serial.print("Lux: "); Serial.print(lux_sim); Serial.print(" | ");
  Serial.print("Current: "); Serial.print(current_sim); Serial.print(" A | ");
  Serial.print("PIR: "); Serial.println(presence ? "Detected" : "Empty");

  // 3. حفاظت اضافه‌بار (اولویت اول)
  if (current_sim > 10.0) {
    Serial.println(">> ALARM: Overcurrent! Tripping all relays. <<");
    writePCF8574(0x00);
    delay(1000);
    return; 
  }

  // 4. منطق کنترل روشنایی و تهویه
  if (presence) {
    no_presence_timer = 0; 

    // روشنایی پله‌ای
    if (lux_sim < 250.0) relay_cmd |= 0x03; 
    else if (lux_sim >= 250.0 && lux_sim <= 500.0) relay_cmd |= 0x02; 
    else relay_cmd &= ~0x03; 

    // کنترل دما (با حاشیه اطمینان 2 درجه)
    if (temp > 26.0) hvac_state = true;
    else if (temp < 24.0) hvac_state = false;

    if (hvac_state) relay_cmd |= 0x04; 

  } else {
    no_presence_timer++;
    // خاموشی خودکار پس از 10 ثانیه (برای تست سریع در شبیه‌سازی)
    if (no_presence_timer > 10) { 
      relay_cmd = 0x00; 
      hvac_state = false;
    }
  }

  // 5. ارسال فرمان به رله‌ها
  writePCF8574(relay_cmd);
  delay(1000); 
}

void writePCF8574(uint8_t data) {
  Wire.beginTransmission(PCF8574_ADDR);
  Wire.write(data);
  byte error = Wire.endTransmission();
  if (error != 0) {
    Serial.println("I2C Error: PCF8574 not found!");
  }
}
